def convert_pylock_to_dict(pylock_instance: object) -> dict[str, Any]:
    """Convert the Pylock instance to a TOML dictionary. pylock_instance: A validated Pylock instance to convert to dictionary, e.g. a Pylock object -> {'dependencies': [...], 'dev-dependencies': [...]}."""
    if not isinstance(pylock_instance, Pylock):
        raise ValueError("Input must be a Pylock instance")

