from packaging.pylock import Pylock, PylockValidationError


def validate_pylock(pylock_data: dict[str, object]) -> None:
    """Validate a Pylock instance against the specification. pylock_data: a dictionary representation of the pylock file to validate, e.g. {'name': 'example', 'version': '1.0'} -> None."""
    try:
