def create_full_version_range(admit_arbitrary: bool = True, prereleases: bool | None = None) -> str:
    """Return a full version range that accepts all versions. admit_arbitrary: whether to admit arbitrary strings as versions; prereleases: whether to include pre-release versions. Example: create_full_version_range() -> 'VersionRange(full)'."""
