from packaging.metadata import Metadata


def create_metadata_from_email(data: str, validate: bool = True) -> dict[str, str | list[str] | None]:
    """Parse metadata from email headers.

    Args:
        data: Email header data containing metadata
        validate: Whether to validate the parsed metadata

    Returns:
        Dictionary representation of the metadata

    Example:
        >>> create_metadata_from_email('Metadata-Version: 2.1\\nName: example-package\\nVersion: 1.0.0\\n', True)
        {'metadata_version': '2.1', 'name': 'example-package', 'version': '1.0.0'}
    """
    try:
        metadata = Metadata.from_email(data, validate=validate)
        # Convert metadata object to dictionary representation
        result = {}

        # Handle basic fields
        if hasattr(metadata, 'metadata_version'):
            result['metadata_version'] = metadata.metadata_version
        if hasattr(metadata, 'name'):
            result['name'] = metadata.name
        if hasattr(metadata, 'version'):
            result['version'] = metadata.version
        if hasattr(metadata, 'summary'):
            result['summary'] = metadata.summary
        if hasattr(metadata, 'home_page'):
            result['home_page'] = metadata.home_page
        if hasattr(metadata, 'author'):
            result['author'] = metadata.author
        if hasattr(metadata, 'author_email'):
            result['author_email'] = metadata.author_email
        if hasattr(metadata, 'license'):
            result['license'] = metadata.license

        # Handle lists
        if hasattr(metadata, 'classifier'):
            result['classifier'] = list(metadata.classifier) if metadata.classifier else []
        if hasattr(metadata, 'requires_dist'):
            result['requires_dist'] = list(metadata.requires_dist) if metadata.requires_dist else []
        if hasattr(metadata, 'requires_python'):
            result['requires_python'] = metadata.requires_python

        return result
    except Exception as e:
        raise ValueError(f"Failed to parse email metadata: {str(e)}") from e
