import sys
from typing import List, Optional, Iterator, Union
from packaging.tags import cpython_tags, Tag


def generate_cpython_tags(
    python_version: Optional[List[int]] = None,
    abis: Optional[List[str]] = None,
    platforms: Optional[List[str]] = None
) -> List[dict]:
    """Generate CPython interpreter tags for wheel compatibility. python_version: target Python version as [major, minor], e.g. [3, 9]. abis: compatible ABIs like ['cp39', 'abi3'], defaults to system ABIs. platforms: compatible platforms like ['linux_x86_64'], defaults to system platforms. Example: generate_cpython_tags([3, 9]) -> [{'interpreter': 'cp39', 'abi': 'cp39', 'platform': 'linux_x86_64'}]"""

    if python_version is not None:
        if not isinstance(python_version, list) or len(python_version) == 0:
            raise ValueError("python_version must be a non-empty list")
        if not all(isinstance(x, int) and x >= 0 for x in python_version):
            raise ValueError("python_version items must be non-negative integers")
        if len(python_version) > 2:
            raise ValueError("python_version must have at most 2 elements")

    if abis is not None and not isinstance(abis, list):
        raise ValueError("abis must be a list")

    if platforms is not None and not isinstance(platforms, list):
        raise ValueError("platforms must be a list")

    try:
        tags = cpython_tags(
            python_version=tuple(python_version) if python_version else None,
            abis=abis,
            platforms=platforms
        )
        return [
            {
                "interpreter": tag.interpreter,
                "abi": tag.abi,
                "platform": tag.platform
            }
            for tag in tags
        ]
    except Exception as e:
        raise ValueError(f"Failed to generate CPython tags: {str(e)}")
